import {calculateBuildable,kitReferenceStatus,lesPaulKitAssembly} from './assemblies.mjs';
import {assemblyRepository} from './assembly-repository.mjs';
import {parseGBP,priceInput} from './data.mjs';
import {discoverKitCandidates,extendPotentiometerDefinition,kitCandidateCategories,kitAdminCandidates} from '../wiring-kits/kit-component-discovery.mjs';
const $=s=>document.querySelector(s),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
let editing=null,rows=[],kitDraft=null,componentRecords=[],assemblyRecords=[];
const form=$('#assembly-form'),field=k=>form.elements.namedItem(k),components=()=>componentRecords;
const kitRoles={potentiometers:{label:'Potentiometers',category:'potentiometers'},neckCapacitor:{label:'Neck tone capacitor',category:'capacitors'},bridgeCapacitor:{label:'Bridge tone capacitor',category:'capacitors'},trebleBleed:{label:'Treble bleed',category:'treble-bleeds'},jack:{label:'Output jack',category:'jacks'},selector:{label:'Selector switch',category:'switches'}};
function error(e){$('#assembly-error').textContent=e.message;}
function refresh(){document.dispatchEvent(new Event('assemblies-changed'));}
export async function renderAssemblies(query='',inventoryRecords=componentRecords){
 componentRecords=inventoryRecords;
 assemblyRecords=[];$('#table-body').replaceChildren();$('#empty').hidden=true;
 assemblyRecords=await assemblyRepository().list();
 const inventory=components(),list=assemblyRecords.filter(a=>[a.name,a.sku,a.category,a.kitDefinition?.family].join(' ').toLowerCase().includes(query));$('#count').textContent=list.length+' assemblies';$('#table-caption').textContent='Products / Assemblies';const header=el('tr');for(const title of ['Assembly','Type','Category','BOM rows','Max buildable','Active','Edit'])header.append(el('th',title));$('#table-head').replaceChildren(header);$('#table-body').replaceChildren();$('#empty').hidden=!!list.length;$('#empty').textContent='No shared assemblies found, or none match your search.';
 for(const a of list){const tr=el('tr'),name=el('td',a.name);name.append(el('small',a.sku));tr.append(name,el('td',a.kind==='wiring-kit'?'Wiring Kit Definition':'Assembly'),el('td',a.category),el('td',String(a.bom.length)));const availability=el('td');showBuildable(availability,a.bom,inventory);tr.append(availability,el('td',a.active?'Active':'Inactive'));const actions=el('td');for(const [label,action] of [['Edit',()=>open(a.id)]]){const button=el('button',label);button.type='button';button.setAttribute('aria-label',label+' '+a.name);button.addEventListener('click',()=>{try{action();}catch(e){$('#status').textContent=e.message;}});actions.append(button);}tr.append(actions);$('#table-body').append(tr);}
}
function open(id=null){editing=id;const a=id?assemblyRecords.find(a=>a.id===id):{name:'',sku:'',category:'Other',kind:'assembly',active:true,bom:[]};if(!a)throw new Error('Assembly no longer exists.');form.reset();for(const key of ['name','sku','category'])field(key).value=a[key];field('kind').value=a.kind==='wiring-kit'?'wiring-kit':'assembly';field('active').checked=a.active;rows=structuredClone(a.bom);kitDraft=a.kind==='wiring-kit'?extendPotentiometerDefinition(a.kitDefinition,components(),{includeUnpermitted:true}):{...structuredClone(lesPaulKitAssembly.kitDefinition),family:'',showOnWiringKits:false,builderEnabled:false,permittedComponentIds:[]};$('#assembly-title').textContent=id?'Edit assembly':'Add assembly';$('#assembly-error').textContent='';renderKitFields();renderRows();$('#assembly-dialog').showModal();}
function renderKitFields(){
 const isKit=field('kind').value==='wiring-kit',root=$('#kit-definition-fields');root.hidden=!isKit;if(!isKit)return;
 field('kitFamily').value=kitDraft.family||'';field('basePrice').value=priceInput(kitDraft.basePrice);field('defaultWiring').value=kitDraft.defaults?.wiring||'50s';field('showOnWiringKits').checked=!!kitDraft.showOnWiringKits;field('builderEnabled').checked=!!kitDraft.builderEnabled;
 const candidates=kitAdminCandidates(components(),kitDraft.permittedComponentIds),choices=$('#kit-permitted-components');choices.replaceChildren();
 for(const category of kitCandidateCategories){
  const categoryItems=candidates[category.key];if(!categoryItems.length)continue;
  const group=el('fieldset');group.append(el('legend',category.label));
  for(const {component,permitted,eligible,reason} of categoryItems){
   const label=el('label'),input=el('input');input.type='checkbox';input.checked=permitted;input.disabled=!eligible&&!permitted;
   input.addEventListener('change',()=>{
    if(input.checked)kitDraft.permittedComponentIds=[...new Set([...kitDraft.permittedComponentIds,component.id])];
    else{kitDraft.permittedComponentIds=kitDraft.permittedComponentIds.filter(id=>id!==component.id);for(const role of Object.keys(kitRoles))if(kitDraft.defaults.componentIds[role]===component.id)kitDraft.defaults.componentIds[role]=null;}
    renderKitDefaults();renderVariantMappings();renderReferenceStatus();
   });
   label.append(input,document.createTextNode(' '+component.name+' · '+component.id+' · '+(permitted?'PERMITTED FOR THIS KIT · ':'')+(eligible?'AVAILABLE / ELIGIBLE':'AVAILABLE / CURRENTLY INELIGIBLE · Reason: '+reason)));
   group.append(label);
  }
  choices.append(group);
 }
 if(!choices.children.length)choices.append(el('p','No Components are currently marked Available in wiring kits.'));
 renderBuilderOptions();renderVariantMappings();renderKitDefaults();renderReferenceStatus();
}
function renderReferenceStatus(){const status=kitReferenceStatus({kind:'wiring-kit',kitDefinition:kitDraft},components());$('#kit-reference-status').textContent=status.warnings.length?status.warnings.join(' '):'All referenced Component IDs exist.';}
function renderBuilderOptions(){const root=$('#kit-builder-options');root.replaceChildren();for(const group of kitDraft.builderOptions){const box=el('fieldset'),legend=el('legend',group.label),enabled=el('label'),enabledInput=el('input');enabledInput.type='checkbox';enabledInput.checked=group.enabled;enabledInput.addEventListener('change',()=>{group.enabled=enabledInput.checked;renderBuilderOptions();});enabled.append(enabledInput,document.createTextNode(' Enable group'));box.append(legend,enabled);const values=el('div');values.className='kit-builder-values';for(const value of group.values){const label=el('label'),input=el('input');input.type='checkbox';input.checked=value.enabled;input.disabled=!group.enabled;input.addEventListener('change',()=>{if(!input.checked&&group.defaultValue===value.key){const next=group.values.find(option=>option.key!==value.key&&option.enabled);if(!next){input.checked=true;return;}group.defaultValue=next.key;}value.enabled=input.checked;renderBuilderOptions();renderVariantMappings();});label.append(input,document.createTextNode(' '+value.label));values.append(label);}const defaultLabel=el('label','Default '+group.label),select=el('select');select.disabled=!group.enabled;for(const value of group.values.filter(value=>value.enabled)){const option=el('option',value.label);option.value=value.key;select.append(option);}select.value=group.defaultValue;select.addEventListener('change',()=>{group.defaultValue=select.value;kitDraft.defaults[group.key]=select.value;});defaultLabel.append(select);box.append(values,defaultLabel);root.append(box);}}
function combinations(groups,index=0,selection={}){if(index===groups.length)return [structuredClone(selection)];const output=[];for(const value of groups[index].values){selection[groups[index].key]=value.key;output.push(...combinations(groups,index+1,selection));}return output;}
function renderVariantMappings(){const root=$('#kit-variant-mappings'),inventory=components();root.replaceChildren();for(const resolver of kitDraft.componentResolvers){const groups=resolver.groupKeys.map(key=>kitDraft.builderOptions.find(group=>group.key===key)),box=el('fieldset'),legend=el('legend',resolver.label);box.append(legend);for(const selection of combinations(groups)){let mapping=resolver.mappings.find(item=>resolver.groupKeys.every(key=>item.selection[key]===selection[key]));if(!mapping)continue;const label=el('label',resolver.groupKeys.map(key=>groups.find(group=>group.key===key).values.find(value=>value.key===selection[key]).label).join(' + ')),select=el('select'),none=el('option','Unavailable / unmapped');none.value='';select.append(none);const candidates=discoverKitCandidates(inventory)[resolver.componentCategory]?.filter(component=>kitDraft.permittedComponentIds.includes(component.id))||[];if(mapping.componentId&&!candidates.some(component=>component.id===mapping.componentId)){const current=inventory.find(component=>component.id===mapping.componentId),option=el('option',(current?.name||'Missing Component: '+mapping.componentId)+' · NOT CURRENTLY PERMITTED');option.value=mapping.componentId;select.append(option);}for(const component of candidates){const option=el('option',component.name+' · '+component.id+(component.active&&component.inKits?'':' · CURRENTLY INELIGIBLE'));option.value=component.id;select.append(option);}select.value=mapping.componentId||'';select.addEventListener('change',()=>{mapping.componentId=select.value||null;renderReferenceStatus();});label.append(select);box.append(label);}root.append(box);}}
function renderKitDefaults(){const inventory=components(),root=$('#kit-default-components');root.replaceChildren();for(const [role,settings] of Object.entries(kitRoles)){if(role==='potentiometers')continue;const label=el('label',settings.label),select=el('select'),none=el('option','None');none.value='';select.append(none);const selected=kitDraft.defaults.componentIds[role];const eligible=new Set(discoverKitCandidates(inventory)[settings.category].map(p=>p.id));if(selected&&!eligible.has(selected)){const missing=el('option','Currently unavailable: '+selected);missing.value=selected;select.append(missing);}for(const component of inventory.filter(p=>eligible.has(p.id)&&kitDraft.permittedComponentIds.includes(p.id))){const option=el('option',component.name+' · '+component.id);option.value=component.id;select.append(option);}select.value=selected||'';select.addEventListener('change',()=>{kitDraft.defaults.componentIds[role]=select.value||null;});label.append(select);root.append(label);}}
function renderRows(focus=false){const inventory=components(),root=$('#assembly-bom');root.replaceChildren();rows.forEach((row,index)=>{const group=el('div');group.className='assembly-bom-row';const label=el('label','Component'),select=el('select');select.required=true;select.setAttribute('aria-label','BOM component '+(index+1));const blank=el('option','Choose component');blank.value='';select.append(blank);if(row.componentId&&!inventory.some(p=>p.id===row.componentId)){const missing=el('option','Missing component: '+row.componentId);missing.value=row.componentId;select.append(missing);}for(const p of inventory){const option=el('option',p.name+' · '+p.sku+(p.active?'':' · INACTIVE'));option.value=p.id;select.append(option);}select.value=row.componentId;select.addEventListener('change',()=>{row.componentId=select.value;updatePreview();});label.append(select);const qtyLabel=el('label','Quantity required'),input=el('input');input.type='number';input.min='1';input.step='1';input.required=true;input.value=row.quantity;input.setAttribute('aria-label','BOM quantity '+(index+1));input.addEventListener('input',()=>{row.quantity=input.value;updatePreview();});qtyLabel.append(input);const remove=el('button','Remove');remove.type='button';remove.setAttribute('aria-label','Remove BOM row '+(index+1));remove.addEventListener('click',()=>{rows.splice(index,1);renderRows();(root.children[Math.min(index,rows.length-1)]?.querySelector('select')||$('#add-bom-row')).focus();});group.append(label,qtyLabel,remove);root.append(group);});if(!rows.length)root.append(el('p','No BOM components. Add the parts required to build one assembly.'));updatePreview();if(focus)root.lastElementChild?.querySelector('select')?.focus();}
$('#add-assembly').addEventListener('click',()=>{try{open();}catch(e){$('#status').textContent=e.message;}});
$('#add-bom-row').addEventListener('click',()=>{rows.push({componentId:'',quantity:1});try{renderRows(true);}catch(e){error(e);}});
field('kind').addEventListener('change',renderKitFields);
form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const kind=field('kind').value;if(kind==='wiring-kit')kitDraft={...kitDraft,family:field('kitFamily').value,basePrice:parseGBP(field('basePrice').value),showOnWiringKits:field('showOnWiringKits').checked,builderEnabled:field('builderEnabled').checked,defaults:{...kitDraft.defaults,wiring:field('defaultWiring').value,...Object.fromEntries(kitDraft.builderOptions.map(group=>[group.key,group.defaultValue]))}};await assemblyRepository().save({name:field('name').value,sku:field('sku').value,category:field('category').value,kind,active:field('active').checked,bom:rows,kitDefinition:kind==='wiring-kit'?kitDraft:undefined},editing);$('#assembly-dialog').close();refresh();$('#status').textContent='Assembly saved to shared configuration. No stock consumed.';}catch(e){error(e);}finally{submit.disabled=false;}});

function showBuildable(target,bom,inventory){
 const result=calculateBuildable(bom,inventory);target.replaceChildren(el('strong',result.quantity===null?'Not calculated':String(result.quantity)));
 if(result.warnings.length){for(const warning of result.warnings)target.append(el('p',warning));target.classList.add('assembly-warning');}else{target.classList.remove('assembly-warning');if(result.limiting.length)target.append(el('small','Limited by: '+result.limiting.map(p=>p.name+' ('+p.stock+' available / '+p.requiredQuantity+' required)').join('; ')));else target.append(el('small','Add a BOM to calculate availability.'));}
}
function updatePreview(){try{showBuildable($('#assembly-buildable'),rows,components());}catch(e){$('#assembly-buildable').textContent='Not calculated. '+e.message;}}
